static inline int nn_infer_gesture(const float *features, float *out_probs) {
    float h1[NN_HIDDEN1_DIM];
    float h2[NN_HIDDEN2_DIM];
    for (int i = 0; i < NN_HIDDEN1_DIM; i++) {
        float sum = NN_B1[i];
        for (int j = 0; j < NN_FEATURE_DIM; j++) sum += features[j] * NN_W1[j][i];
        h1[i] = (sum > 0.0f) ? sum : 0.0f; // ReLU
    }
    for (int i = 0; i < NN_HIDDEN2_DIM; i++) {
        float sum = NN_B2[i];
        for (int j = 0; j < NN_HIDDEN1_DIM; j++) sum += h1[j] * NN_W2[j][i];
        h2[i] = (sum > 0.0f) ? sum : 0.0f; // ReLU
    }
    float max_logit = -1e9f;
    float logits[NN_CLASSES];
    for (int i = 0; i < NN_CLASSES; i++) {
        logits[i] = NN_B3[i];
        for (int j = 0; j < NN_HIDDEN2_DIM; j++) logits[i] += h2[j] * NN_W3[j][i];
        if (logits[i] > max_logit) max_logit = logits[i];
    }
    float sum_exp = 0.0f;
    for (int i = 0; i < NN_CLASSES; i++) {
        out_probs[i] = expf(logits[i] - max_logit);
        sum_exp += out_probs[i];
    }
    int best_class = 0;
    float best_prob = 0.0f;
    for (int i = 0; i < NN_CLASSES; i++) {
        out_probs[i] /= sum_exp;
        if (out_probs[i] > best_prob) { best_prob = out_probs[i]; best_class = i; }
    }
    return best_class;
}
